flags.typeql:
match
  $p isa person;
  $m isa movie;
  (producer: $p, film: $m) isa produced;
  $p has born $bornp;
  $bornp > 1960;
  $m has title $titlem;
  $m has votes $votesm;
  $m has tagline $taglinem;
  $m has released $releasedm;
limit 5;
fetch {
  "title": $titlem,
  "votes": $votesm,
  "tagline": $taglinem,
  "released": $releasedm
};

match
  $m isa movie, has title $t;
  (actor: $p, film: $m) isa acted_in;
reduce $roleCount = count($p) groupby $t;
sort $roleCount desc;
limit 5;
fetch {
  "movie": $t,
  "roleCount": $roleCount
};

match
  $d isa person, has name "Nancy Meyers";
  (director: $d, film: $m) isa directed;
  $m has title $t, has released $r;
  $ai isa acted_in (actor: $a, film: $m), has roles $roles;
  $a has name $n;
sort $r asc;
limit 3;
fetch {
  "movie": $t,
  "actor": $n,
  "roles": $roles
};

match
  $m isa movie;
  $m has released $releasedm;
  $releasedm >= 1980;
  $releasedm <= 1990;
  (reviewer: $r, film: $m) isa reviewed, has rating $ratingr;
  $ratingr > 80;
  $m has title $titlem;
fetch {
  "title": $titlem,
  "released": $releasedm
};

match
  $p isa person, has name $n, has born $b;
  $b < 1950;
  $rev isa reviewed (reviewer: $p, film: $m), has summary $s;
  $s like ".*funny.*";
sort $b asc;
limit 3;
fetch {
  "name": $n
};

